    /* ===== src/ui/mask.js ===== */
    /*
     * Masked API key boxes, the same way on every page.
     *
     * A key box must hide what is typed WITHOUT being a password field: Chrome,
     * Edge and password managers offer to save (and sync) whatever is typed in a
     * type="password" box, and a Full key in a synced password store is a key
     * outside our control. So the box is type="text" and CSS hides the letters
     * (-webkit-text-security, which Chrome, Edge and Safari support).
     *
     * Where CSS cannot mask (some Firefox builds), a plain text box would show
     * the key in the clear; there, and only there, it falls back to a password
     * box with saving discouraged (autocomplete off, password-manager opt-outs).
     */

    /** Can this browser hide a text box's letters with CSS? */
    function cssMaskSupported() {
        try {
            return Boolean(
                typeof CSS !== 'undefined' &&
                    CSS.supports &&
                    (CSS.supports('-webkit-text-security', 'disc') || CSS.supports('text-security', 'disc')),
            );
        } catch {
            return false;
        }
    }

    /** The attributes every key box gets: no autofill, no spellcheck, no password-manager capture. */
    function keyInputAttrs() {
        return {
            type: cssMaskSupported() ? 'text' : 'password',
            autocomplete: 'off',
            autocapitalize: 'off',
            autocorrect: 'off',
            spellcheck: 'false',
            'data-lpignore': 'true',
            'data-1p-ignore': 'true',
            'data-bwignore': 'true',
            'data-form-type': 'other',
        };
    }

    /** A revealed saved key is taken out of the box again after this long. */
    const REVEAL_MS = 60000;

    /**
     * Show / hide for one key box.
     *
     * @param {HTMLInputElement} input
     * @param {string} maskedClass - the page's CSS class that hides the letters
     * @param {object} [opts]
     * @param {function} [opts.onReveal] - () => the saved key, put in the box only while shown
     * @param {function} [opts.onChange] - (hidden) => void, e.g. to relabel a Show button
     * @returns {{hidden: function, toggle: function, hide: function}}
     */
    function keyMask(input, maskedClass, { onReveal = null, onChange = () => {} } = {}) {
        const byCss = input.type !== 'password';
        let hidden = true;
        let revealed = false;
        let timer = null;

        const apply = () => {
            if (byCss) input.classList.toggle(maskedClass, hidden);
            else input.type = hidden ? 'password' : 'text';
            onChange(hidden);
        };

        const hide = () => {
            if (timer) clearTimeout(timer);
            timer = null;
            hidden = true;
            // A saved key shown on request never stays in the box: any script
            // that can reach the box could read it.
            if (revealed) {
                input.value = '';
                revealed = false;
            }
            apply();
        };

        const show = () => {
            hidden = false;
            if (!input.value && onReveal) {
                input.value = onReveal() || '';
                revealed = true;
                timer = setTimeout(hide, REVEAL_MS);
            }
            apply();
        };

        if (byCss) input.classList.add(maskedClass);
        return {
            hidden: () => hidden,
            toggle: () => (hidden ? show() : hide()),
            hide,
        };
    }

    /* ===== src/api/third.js ===== */
    /*
     * A client for one keyed third party (FFScouter, TornStats): one host,
     * asserted on the resolved URL; its own per-minute window shared across
     * tabs; a pause when the service says so; nothing from a hidden tab; the
     * key redacted from every error. The Torn key never reaches these clients:
     * each holds only the key its own service issued (or already has).
     */



    class ThirdPartyError extends Error {
        constructor(message, { service = '', http = null, code = null, paused = false, retryAfterS = null, deadKey = false } = {}) {
            super(message);
            this.name = 'ThirdPartyError';
            this.service = service;
            this.http = http;
            this.code = code;
            this.paused = paused;
            this.retryAfterS = retryAfterS;
            this.deadKey = deadKey;
        }
    }

    function tpSleep(ms) {
        return new Promise((r) => setTimeout(r, ms));
    }

    function redactThirdKey(text, key) {
        let out = String(text === null || text === undefined ? '' : text);
        if (key) out = out.split(key).join('<redacted>');
        return out.replace(/key=[A-Za-z0-9_-]{8,}/g, 'key=<redacted>');
    }

    class ThirdPartyClient {
        /**
         * @param {object} o
         * @param {string} o.service - name for messages
         * @param {string} o.host - the only hostname this client may reach
         * @param {function} o.getKey - () => this service's key
         * @param {number} [o.maxPerMinute]
         * @param {function} [o.fetchImpl]
         * @param {function} [o.now]
         * @param {function} [o.sleep]
         * @param {function} [o.isVisible]
         * @param {function} [o.loadShared] - () => {recent:number[], pauseUntil}
         * @param {function} [o.saveShared]
         */
        constructor({ service, host, getKey, maxPerMinute = 30, fetchImpl = gmFetch, now = () => Date.now(), sleep = tpSleep, isVisible = () => true, loadShared = null, saveShared = null }) {
            this.service = service;
            this.host = host;
            this.getKey = getKey;
            this.maxPerMinute = maxPerMinute;
            this.fetchImpl = fetchImpl;
            this.now = now;
            this.sleep = sleep;
            this.isVisible = isVisible;
            this.loadShared = loadShared;
            this.saveShared = saveShared;
            this.recent = [];
            this.pauseUntil = 0;
            this.chain = Promise.resolve();
            this.dead = false;
        }

        shared() {
            try {
                const s = this.loadShared ? this.loadShared() : null;
                return s && typeof s === 'object' ? s : {};
            } catch {
                return {};
            }
        }

        writeShared(s) {
            try {
                if (this.saveShared) this.saveShared(s);
            } catch {
                // best-effort
            }
        }

        window(t) {
            const s = this.shared();
            const list = Array.isArray(s.recent) ? s.recent : this.recent;
            return list.filter((x) => Number.isFinite(x) && t - x < 60000).sort((a, b) => a - b);
        }

        pausedUntil() {
            return Math.max(this.pauseUntil, Number(this.shared().pauseUntil) || 0);
        }

        stats() {
            const t = this.now();
            const used = this.window(t).length;
            return { usedLastMinute: used, remaining: Math.max(0, this.maxPerMinute - used), paused: t < this.pausedUntil() };
        }

        pause(seconds) {
            this.pauseUntil = this.now() + Math.max(1, seconds) * 1000;
            this.writeShared({ ...this.shared(), recent: this.window(this.now()), pauseUntil: this.pauseUntil });
        }

        async waitForSlot() {
            for (;;) {
                if (!this.isVisible()) {
                    await this.sleep(1000);
                    continue;
                }
                const t = this.now();
                const w = this.window(t);
                if (w.length < this.maxPerMinute) {
                    w.push(t);
                    this.recent = w;
                    this.writeShared({ ...this.shared(), recent: w });
                    return;
                }
                await this.sleep(Math.max(50, 60000 - (t - w[w.length - this.maxPerMinute]) + 25));
            }
        }

        /** Check a URL before anything is sent: right host, https. Exposed for tests. */
        checkUrl(url) {
            const u = new URL(url);
            if (u.hostname !== this.host || u.protocol !== 'https:') throw new ThirdPartyError('Refusing to contact ' + u.hostname + '.', { service: this.service });
            return u;
        }

        /** One request: queued, rate-limited, host-checked, key-redacted. `build(key)` returns the URL. */
        request(build, init = {}) {
            const run = () => this.execute(build, init);
            const p = this.chain.catch(() => {}).then(run);
            this.chain = p.catch(() => {});
            return p;
        }

        async execute(build, init) {
            const key = this.getKey ? this.getKey() : '';
            if (!key) throw new ThirdPartyError('No ' + this.service + ' key saved.', { service: this.service, deadKey: true });
            if (this.dead) throw new ThirdPartyError(this.service + ' rejected this key. Save a new one.', { service: this.service, deadKey: true });
            const paused = () => {
                if (this.now() < this.pausedUntil()) {
                    const s = Math.ceil((this.pausedUntil() - this.now()) / 1000);
                    throw new ThirdPartyError(this.service + ' asked us to wait ' + s + ' s.', { service: this.service, paused: true, retryAfterS: s });
                }
            };
            paused();
            const url = this.checkUrl(build(key)).toString();
            await this.waitForSlot();
            paused();
            let res;
            try {
                res = await this.fetchImpl(url, init);
            } catch (e) {
                throw new ThirdPartyError(this.service + ' network error: ' + redactThirdKey(e && e.message, key), { service: this.service });
            }
            let body = null;
            try {
                body = await res.json();
            } catch {
                body = null;
            }
            return { status: res.status, ok: res.ok, body, key };
        }
    }

    /* ===== src/api/ffscouter.js ===== */
    /*
     * FFScouter (ffscouter.com/api/v1): stat estimates for players you haven't
     * fought, and target lists. The key is the user's own Torn key registered
     * at FFScouter - FFScouter already has it; it goes nowhere else from here.
     * Credited wherever its data shows (DESIGN §6), with a link to its home page,
     * where its data policy lives (research-third-party-api.md §1.8).
     */



    const FFS_HOST = 'ffscouter.com';
    const FFS_BASE = 'https://ffscouter.com/api/v1/';
    const FFS_SITE_URL = 'https://ffscouter.com/';
    const FFS_POLICY_URL = 'https://ffscouter.com/';

    /** get-stats allows 120/min per IP; we keep to half. */
    const FFS_MAX_PER_MINUTE = 60;
    const FFS_BATCH = 205;

    /** Estimates are cached 5 min in memory, 1 h in storage (FFScouter's guidance). */
    const FFS_MEMORY_MS = 5 * 60 * 1000;
    const FFS_STORED_MS = 60 * 60 * 1000;

    function makeFfsClient(opts) {
        return new ThirdPartyClient({ service: 'FFScouter', host: FFS_HOST, maxPerMinute: FFS_MAX_PER_MINUTE, ...opts });
    }

    function url(path, key, params = {}) {
        const u = new URL(path, FFS_BASE);
        u.searchParams.set('key', key);
        for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== null && v !== '') u.searchParams.set(k, String(v));
        return u.toString();
    }

    /** An FFScouter answer: throws on its error envelope, pauses on 429 (codes 20/21). */
    function ffsUnwrap(client, r) {
        const b = r.body;
        if (r.ok && b && (Array.isArray(b) || b.code === undefined)) return b;
        const code = b && Number.isFinite(Number(b.code)) ? Number(b.code) : null;
        const retry = b && Number(b.retry_after_seconds) > 0 ? Number(b.retry_after_seconds) : null;
        if (r.status === 429 || code === 20 || code === 21) {
            client.pause(retry || 60);
            throw new ThirdPartyError('FFScouter asked us to slow down.', { service: 'FFScouter', http: r.status, code, paused: true, retryAfterS: retry || 60 });
        }
        const dead = code === 1 || code === 2 || code === 6 || code === 4010 || code === 4011;
        if (dead) client.dead = true;
        const msg = code === 6 ? 'This key is not registered at FFScouter.' : b && b.error ? String(b.error) : 'HTTP ' + r.status;
        throw new ThirdPartyError('FFScouter: ' + msg.split(r.key || '\u0000').join('<redacted>'), { service: 'FFScouter', http: r.status, code, deadKey: dead });
    }

    /** One row as the estimator reads it; null fields where FFScouter has nothing. */
    function normalizeFfsRow(row) {
        const id = Number(row && row.player_id);
        const has = row && row.bs_estimate > 0 && row.last_updated > 0;
        return {
            playerId: id,
            bsEstimate: has ? Number(row.bs_estimate) : null,
            bssPublic: row && row.bss_public > 0 ? Number(row.bss_public) : null,
            fairFight: row && row.fair_fight > 0 ? Number(row.fair_fight) : null,
            updatedAt: has ? Number(row.last_updated) * 1000 : null,
            source: row && row.source ? String(row.source) : null,
            distribution: row && row.distribution && row.distribution.stats_percentage ? { ...row.distribution.stats_percentage } : null,
        };
    }

    /**
     * Estimates for up to any number of ids, in batches of 205. Every id asked
     * for comes back (a missing one as an empty row, as FF Scouter V2 does).
     * @returns {Promise<Map<number, object>>}
     */
    async function fetchFfsStats(client, playerIds) {
        const list = [...new Set((playerIds || []).map(Number).filter((x) => x > 0))];
        const out = new Map();
        for (let i = 0; i < list.length; i += FFS_BATCH) {
            const batch = list.slice(i, i + FFS_BATCH);
            const r = await client.request((key) => url('get-stats', key, { targets: batch.join(',') }));
            const rows = ffsUnwrap(client, r);
            for (const row of Array.isArray(rows) ? rows : []) out.set(Number(row.player_id), normalizeFfsRow(row));
            for (const id of batch) if (!out.has(id)) out.set(id, normalizeFfsRow({ player_id: id }));
        }
        return out;
    }

    /** Is this key registered at FFScouter? */
    async function checkFfsKey(client) {
        const r = await client.request((key) => url('check-key', key));
        const b = ffsUnwrap(client, r);
        return { registered: Boolean(b.is_registered), premium: Boolean(b.is_premium), policyUpdate: Boolean(b.policy_update_required) };
    }

    /**
     * Target list: {preset:'respect'|'level'} or level/FF filters. No match is
     * HTTP 404 code 17: an empty list, not an error.
     */
    async function fetchFfsTargets(client, { preset = null, minLevel = null, maxLevel = null, inactiveOnly = 1, factionless = null, maxFf = null, minFf = null, limit = 50 } = {}) {
        const params = preset ? { preset, limit } : { minlevel: minLevel, maxlevel: maxLevel, inactiveonly: inactiveOnly, factionless, minff: minFf, maxff: maxFf, limit };
        const r = await client.request((key) => url('get-targets', key, params));
        if (r.status === 404 && r.body && Number(r.body.code) === 17) return [];
        const b = ffsUnwrap(client, r);
        return (b.targets || []).map((t) => ({
            playerId: Number(t.player_id),
            name: t.name || null,
            level: Number(t.level) || null,
            fairFight: t.fair_fight > 0 ? Number(t.fair_fight) : null,
            bsEstimate: t.bs_estimate > 0 ? Number(t.bs_estimate) : null,
            bssPublic: t.bss_public > 0 ? Number(t.bss_public) : null,
            lastAction: t.last_action ? Number(t.last_action) * 1000 : null,
            hospitalUntil: t.hospital_until ? Number(t.hospital_until) * 1000 : null,
        }));
    }

    /* ===== src/api/tornstats.js ===== */
    /*
     * TornStats spies (optional): exact stats your faction shared. The key is
     * the Torn key on the user's TornStats account (TornStats has it already)
     * and sits in the URL PATH, so the host is asserted and URLs are never
     * logged. research-third-party-api.md §2.
     */



    const TS_HOST = 'www.tornstats.com';
    const TS_BASE = 'https://www.tornstats.com/api/v2/';
    const TS_TOS_URL = 'https://tornstats.com/tos';

    /** TornStats documents 100/min; we keep to 30. */
    const TS_MAX_PER_MINUTE = 30;

    function makeTsClient(opts) {
        return new ThirdPartyClient({ service: 'TornStats', host: TS_HOST, maxPerMinute: TS_MAX_PER_MINUTE, ...opts });
    }

    const seg = (x) => encodeURIComponent(String(x).replace(/[^A-Za-z0-9_]/g, ''));

    function tsUnwrap(client, r) {
        const b = r.body;
        if (b && b.status === false) {
            const dead = r.status === 404 || /user not found|invalid/i.test(String(b.message || ''));
            if (dead) client.dead = true;
            throw new ThirdPartyError('TornStats: ' + String(b.message || 'refused').split(r.key || '\u0000').join('<redacted>'), { service: 'TornStats', http: r.status, deadKey: dead });
        }
        if (r.status === 429) {
            client.pause(60);
            throw new ThirdPartyError('TornStats asked us to slow down.', { service: 'TornStats', http: 429, paused: true, retryAfterS: 60 });
        }
        if (!r.ok || !b) throw new ThirdPartyError('TornStats HTTP ' + r.status, { service: 'TornStats', http: r.status });
        return b;
    }

    function spyOf(s) {
        if (!s || s.status === false) return null;
        const v = (k) => (Number(s[k]) > 0 ? Number(s[k]) : null);
        const ts = Number(s.timestamp) || 0;
        const stats = { str: v('strength'), spd: v('speed'), def: v('defense'), dex: v('dexterity') };
        if (!Object.values(stats).some(Boolean) && !v('total')) return null;
        return { ...stats, total: v('total'), at: ts > 0 ? ts * 1000 : null };
    }

    /** One player's spy, or null. */
    async function fetchSpyUser(client, userId) {
        const r = await client.request((key) => TS_BASE + seg(key) + '/spy/user/' + seg(userId));
        return spyOf(tsUnwrap(client, r).spy);
    }

    /** A faction's members with spies: {[playerId]: spy}. */
    async function fetchSpyFaction(client, factionId) {
        const r = await client.request((key) => TS_BASE + seg(key) + '/spy/faction/' + seg(factionId));
        const f = tsUnwrap(client, r).faction || {};
        const out = {};
        for (const [id, m] of Object.entries(f.members || {})) {
            const s = spyOf(m && m.spy);
            if (s) out[Number(id)] = s;
        }
        return out;
    }

    /* ===== src/core/zip.js ===== */
    /*
     * A tiny .zip writer and reader for the learning export (Settings ›
     * Developer). Stored entries only (no compression): the files are small
     * JSON, and a zip any tool can open needs nothing more. Pure: bytes in,
     * bytes out; the page does the download.
     */

    const ZIP_CRC_TABLE = (() => {
        const t = new Uint32Array(256);
        for (let n = 0; n < 256; n++) {
            let c = n;
            for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
            t[n] = c >>> 0;
        }
        return t;
    })();

    function crc32(bytes) {
        let c = 0xffffffff;
        for (let i = 0; i < bytes.length; i++) c = ZIP_CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
        return (c ^ 0xffffffff) >>> 0;
    }

    function zipDosTime(date) {
        const d = new Date(date);
        const time = (d.getUTCHours() << 11) | (d.getUTCMinutes() << 5) | Math.floor(d.getUTCSeconds() / 2);
        const day = ((d.getUTCFullYear() - 1980) << 9) | ((d.getUTCMonth() + 1) << 5) | d.getUTCDate();
        return { time, day };
    }

    /**
     * @param {{name:string, data:string|Uint8Array}[]} files
     * @param {number} [at] - the time stamped on every entry (ms)
     * @returns {Uint8Array}
     */
    function makeZip(files, at = Date.now()) {
        const enc = new TextEncoder();
        const { time, day } = zipDosTime(at);
        const locals = [];
        const centrals = [];
        let offset = 0;
        for (const f of files) {
            const name = enc.encode(f.name);
            const data = typeof f.data === 'string' ? enc.encode(f.data) : f.data;
            const crc = crc32(data);
            const lh = new DataView(new ArrayBuffer(30));
            lh.setUint32(0, 0x04034b50, true);
            lh.setUint16(4, 20, true);
            lh.setUint16(6, 0x0800, true); // UTF-8 names
            lh.setUint16(8, 0, true); // stored
            lh.setUint16(10, time, true);
            lh.setUint16(12, day, true);
            lh.setUint32(14, crc, true);
            lh.setUint32(18, data.length, true);
            lh.setUint32(22, data.length, true);
            lh.setUint16(26, name.length, true);
            lh.setUint16(28, 0, true);
            locals.push(new Uint8Array(lh.buffer), name, data);
            const ch = new DataView(new ArrayBuffer(46));
            ch.setUint32(0, 0x02014b50, true);
            ch.setUint16(4, 20, true);
            ch.setUint16(6, 20, true);
            ch.setUint16(8, 0x0800, true);
            ch.setUint16(10, 0, true);
            ch.setUint16(12, time, true);
            ch.setUint16(14, day, true);
            ch.setUint32(16, crc, true);
            ch.setUint32(20, data.length, true);
            ch.setUint32(24, data.length, true);
            ch.setUint16(28, name.length, true);
            ch.setUint32(42, offset, true);
            centrals.push(new Uint8Array(ch.buffer), name);
            offset += 30 + name.length + data.length;
        }
        const cdSize = centrals.reduce((a, b) => a + b.length, 0);
        const end = new DataView(new ArrayBuffer(22));
        end.setUint32(0, 0x06054b50, true);
        end.setUint16(8, files.length, true);
        end.setUint16(10, files.length, true);
        end.setUint32(12, cdSize, true);
        end.setUint32(16, offset, true);
        const parts = [...locals, ...centrals, new Uint8Array(end.buffer)];
        const out = new Uint8Array(parts.reduce((a, b) => a + b.length, 0));
        let p = 0;
        for (const part of parts) {
            out.set(part, p);
            p += part.length;
        }
        return out;
    }

    /**
     * Read a zip made by makeZip (stored entries). Compressed entries are
     * skipped and named in `skipped`.
     * @param {Uint8Array} bytes
     * @returns {{files:{[name:string]: string}, skipped:string[]}}
     */
    function readZip(bytes) {
        const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
        const dec = new TextDecoder();
        let e = bytes.length - 22;
        while (e >= 0 && dv.getUint32(e, true) !== 0x06054b50) e--;
        if (e < 0) throw new Error('Not a zip file');
        const count = dv.getUint16(e + 10, true);
        let p = dv.getUint32(e + 16, true);
        const files = {};
        const skipped = [];
        for (let i = 0; i < count; i++) {
            if (dv.getUint32(p, true) !== 0x02014b50) throw new Error('Broken zip directory');
            const method = dv.getUint16(p + 10, true);
            const size = dv.getUint32(p + 20, true);
            const nameLen = dv.getUint16(p + 28, true);
            const extra = dv.getUint16(p + 30, true);
            const comment = dv.getUint16(p + 32, true);
            const local = dv.getUint32(p + 42, true);
            const name = dec.decode(bytes.subarray(p + 46, p + 46 + nameLen));
            const lName = dv.getUint16(local + 26, true);
            const lExtra = dv.getUint16(local + 28, true);
            const start = local + 30 + lName + lExtra;
            if (method === 0) files[name] = dec.decode(bytes.subarray(start, start + size));
            else skipped.push(name);
            p += 46 + nameLen + extra + comment;
        }
        return { files, skipped };
    }

    /* ===== src/ui/app/developer.js ===== */
    /*
     * Settings › Developer (mockups/round3/X-settings.html, Y-developer.html).
     * Everyone: export the learning data as a .zip (names and ids left out) so
     * a friend can send theirs. The developer key (owner and Claude) unlocks
     * the rest: import a friend's export, what the app learned in plain words
     * and charts, the simulation check, and the raw details. The key is checked
     * against a SHA-256 in this (public) script, so it only hides views; it
     * never unlocks data or actions.
     */











    /** SHA-256 of the developer key (the key itself lives only on the owner's laptop). */
    const DEV_KEY_SHA256 = '867b596b74aed64f484c60611ac2b3cc03c7ceb45230a140e4be5a8330d660e2';

    async function sha256Hex(text) {
        const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(String(text)));
        return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
    }

    async function checkDevKey(text) {
        return (await sha256Hex(String(text || '').trim())) === DEV_KEY_SHA256;
    }

    function dateShort(t0) {
        const d = new Date(t0);
        return d.getUTCDate() + ' ' + MONTH_NAMES[d.getUTCMonth()];
    }

    /** Download bytes as a file from our own page (never on torn.com). */
    function download(bytes, name) {
        const url = URL.createObjectURL(new Blob([bytes], { type: 'application/zip' }));
        const a = h('a', { href: url, download: name, style: 'display:none' });
        document.body.appendChild(a);
        a.click();
        setTimeout(() => {
            URL.revokeObjectURL(url);
            a.remove();
        }, 1000);
    }

    function exportZip(ctx) {
        const d = ctx.dev.data();
        const files = exportFiles({ samples: d.samples, fights: d.fights, gymLog: d.gymLog, learned: d.learned, version: d.version, now: Date.now() });
        download(makeZip(files), 'learning-' + new Date().toISOString().slice(0, 10) + '.zip');
    }

    /** The Settings card (locked: export for everyone, unlock for the owner). */
    function developerSection(m, ctx) {
        if (!ctx.dev) return null;
        const d = ctx.dev.data();
        const unlocked = ctx.dev.unlocked();
        const keyIn = h('input', { ...keyInputAttrs(), class: 'inp' + (keyInputAttrs().type === 'text' ? ' masked' : ''), placeholder: 'Developer key', 'aria-label': 'Developer key', style: 'width:220px' });
        keyMask(keyIn, 'masked');
        const msg = h('span', { class: 'msg' });
        const unlock = async () => {
            msg.textContent = 'Checking…';
            const ok = await checkDevKey(keyIn.value);
            keyIn.value = '';
            if (ok) {
                ctx.dev.setUnlocked(true);
                ctx.ui.devPage = true;
                ctx.rerender();
            } else {
                msg.className = 'msg bad';
                msg.textContent = 'That isn’t the developer key.';
            }
        };
        keyIn.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') unlock();
        });
        return h('div', { class: 'sec' }, [
            h('div', {}, [h('h3', { text: 'Developer' }), h('span', { class: 'state ' + (unlocked ? 'ok' : 'off') }, [h('i'), unlocked ? 'Unlocked' : 'Locked'])]),
            h('div', { class: 'secbody' }, [
                h('div', { class: 'row', style: 'flex-wrap:wrap' }, [
                    h('span', {}, [h('b', { class: 'white', text: 'Learning data' }), h('span', { class: 'muted', text: ' · what Pumping Iron learned from your trains (' + fmtInt(d.samples.length) + ' sessions) and fights (' + fmtInt(d.fights.length) + '). Names and ids are left out.' })]),
                    h('span', { class: 'grow' }),
                    h('button', { class: 'btn sm', type: 'button', onclick: () => exportZip(ctx), text: 'Export as .zip' }),
                ]),
                unlocked
                    ? h('div', { class: 'row' }, [h('button', { class: 'btn sm primary', type: 'button', onclick: () => { ctx.ui.devPage = true; ctx.rerender(); }, text: 'Open the Developer page' }), h('button', { class: 'btn sm ghost', type: 'button', onclick: () => { ctx.dev.setUnlocked(false); ctx.rerender(); }, text: 'Lock' })])
                    : h('div', { class: 'row', style: 'flex-wrap:wrap' }, [keyIn, h('button', { class: 'btn sm', type: 'button', onclick: unlock, text: 'Unlock' }), h('span', { class: 'muted', style: 'font-size:13px', text: 'For the owner only: what it learned (graphs, plain words), import a friend’s export, and the raw details.' }), msg]),
            ]),
        ]);
    }

    /* ------------------------------------------------------------- the page */

    /** Simulated sessions from the engine's own formula (the learner's self-check; docs/sims/learn-sim.mjs). */
    function simSessions({ stat, S, H = 5000, dots = 7.3, E = 10, n = 30, truth = 1, seed = 7 }) {
        let x = seed;
        const rnd = () => ((x = (x * 1103515245 + 12345) % 2147483648) / 2147483648);
        const out = [];
        let s = S;
        for (let i = 0; i < n; i++) {
            const trains = 15 + Math.floor(rnd() * 25);
            let st = s;
            let hh = H;
            let pred = s;
            for (let k = 0; k < trains; k++) {
                st += gainPerTrain(stat, st, hh, dots, E, truth);
                pred += gainPerTrain(stat, pred, hh, dots, E, 1);
                hh = Math.max(0, hh - E * (0.4 + rnd() * 0.2));
            }
            out.push({ at: i, stat, trains, S: s, H, dots, E, perks: 1, predicted: pred - s, actual: st - s });
            s = st;
        }
        return out;
    }

    /** S1 (the model already right: no change) and S2 (a hidden +4% perk: found), run now in this page. */
    function selfCheck() {
        const t0 = performance.now();
        const s1 = learnGym(simSessions({ stat: 'spd', S: 4.06e6 }), { now: 1e9 });
        const s2 = learnGym(simSessions({ stat: 'spd', S: 4.06e6, truth: 1.04, seed: 11 }), { now: 1e9 });
        const ms = performance.now() - t0;
        return [
            { name: 'S1 model already right', ok: !s1.accepted, text: s1.accepted ? 'changed (wrong)' : 'no false change' },
            { name: 'S2 hidden +4% perk', ok: s2.accepted && Math.abs(s2.model.mult.spd - 1.04) < 0.01, text: s2.accepted ? 'found ×' + s2.model.mult.spd.toFixed(3) : 'not found' },
            { name: 'Time', ok: ms < 500, text: Math.round(ms) + ' ms' },
        ];
    }

    /**
     * Money log fields (round 7, C.0): your money log by Torn's log type, with
     * the names of each type's data fields and which one was read as the amount.
     * Names and counts only, never an amount: the money accounts are written
     * from this, not from guesses. It is also in the report zip, for everyone.
     */
    function moneyFieldsBlock(dev) {
        const mf = dev.moneyFields ? dev.moneyFields() : { at: null, list: [] };
        const head = sectionHead('Money log fields', meta([mf.list.length ? mf.list.length + ' log types · read ' + new Date(mf.at).toISOString().slice(0, 16).replace('T', ' ') + ' UTC · names only, never an amount' : 'names only, never an amount']), null, 'h3');
        if (!mf.list.length) return h('div', {}, [head, h('p', { class: 'muted', style: 'margin:0', text: 'Nothing read yet: the money log needs the Full key (Settings), and is read every 6 hours. A log read before this version has no field names: save the Full key again, or wait for the next read.' })]);
        const amountWords = (a) => Object.entries(a || {}).sort((x, y) => y[1] - x[1]).map(([k, n]) => k + ' × ' + n).join(', ');
        const rows = mf.list.map((r) =>
            h('tr', {}, [
                h('td', {}, [h('b', { class: 'w', text: r.title || '(no title)' }), h('br'), h('small', { class: 'muted', text: r.category || '' })]),
                h('td', { class: 'r', text: r.type === null ? '—' : String(r.type) }),
                h('td', { class: 'r', text: fmtInt(r.lines) }),
                h('td', { class: 'r', text: String(r.days) }),
                h('td', { style: 'white-space:normal', text: r.fields.map((f) => f.name + ' (' + f.is + ')').join(', ') || 'no data fields' }),
                h('td', { class: /none read/.test(amountWords(r.amount)) ? 'c-warn' : '', style: 'white-space:normal', text: amountWords(r.amount) }),
            ]),
        );
        return h('div', {}, [
            head,
            h('table', { class: 'tbl num' }, [h('thead', {}, [h('tr', {}, [h('th', { text: 'Log line' }), h('th', { class: 'r', style: 'width:60px', text: 'Type' }), h('th', { class: 'r', style: 'width:56px', text: 'Lines' }), h('th', { class: 'r', style: 'width:52px', text: 'Days' }), h('th', { text: 'Data fields' }), h('th', { style: 'width:180px', text: 'Read as the amount' })])]), h('tbody', {}, rows)]),
            h('div', { class: 'note2', text: 'A line listed under two of Torn’s categories counts once. “(none read)”: no field of that line was taken as its amount today.' }),
        ]);
    }

    function renderDeveloper(m, ctx) {
        const dev = ctx.dev;
        const mine = dev.data();
        const friend = ctx.ui.devImport || null;
        const src = ctx.ui.devSource === 'friend' && friend ? 'friend' : 'mine';
        const now = Date.now();
        // Mine: what the app kept. A friend's export: the learners run on it here (never merged into your model).
        // The learners run once per data set shown (not on every redraw).
        const runOnce = (holder, samples, fights) => holder.learned || (holder.learned = { at: now, gym: learnGym(samples, { now }), fights: learnFights(fights, { now }) });
        const set = src === 'friend' ? { samples: friend.samples, fights: friend.fights, learned: runOnce(friend, friend.samples, friend.fights) } : { samples: mine.samples, fights: mine.fights, learned: mine.learned || runOnce(ctx.ui.devMine || (ctx.ui.devMine = {}), mine.samples, mine.fights) };
        const gym = set.learned.gym;
        const fights = set.learned.fights;

        const fileIn = h('input', { type: 'file', accept: '.zip,application/zip', style: 'display:none' });
        const importMsg = h('span', { class: 'msg' });
        fileIn.addEventListener('change', async () => {
            const f = fileIn.files && fileIn.files[0];
            if (!f) return;
            try {
                const bytes = new Uint8Array(await f.arrayBuffer());
                const data = importFiles(readZip(bytes).files);
                ctx.ui.devImport = { ...data, name: f.name };
                ctx.ui.devSource = 'friend';
                ctx.rerender();
            } catch (e) {
                importMsg.className = 'msg bad';
                importMsg.textContent = String((e && e.message) || e);
            }
        });
        const seg = h('div', { class: 'seg', role: 'group', 'aria-label': 'Data' }, [
            h('button', { type: 'button', 'aria-pressed': String(src === 'mine'), onclick: () => { ctx.ui.devSource = 'mine'; ctx.rerender(); }, text: 'Mine · ' + mine.samples.length + ' sessions · ' + mine.fights.length + ' fights' }),
            friend ? h('button', { type: 'button', 'aria-pressed': String(src === 'friend'), onclick: () => { ctx.ui.devSource = 'friend'; ctx.rerender(); }, text: 'Friend’s export · ' + friend.samples.length + ' sessions' }) : null,
        ]);
        const ctl = [
            h('button', { class: 'btn sm ghost', type: 'button', onclick: () => { ctx.ui.devPage = false; ctx.rerender(); }, text: '‹ Settings' }),
            h('b', { class: 'white', text: 'Developer' }),
            h('span', { class: 'tag good', text: 'Unlocked' }),
            h('span', { class: 'sep' }),
            t('lab', 'Data'),
            seg,
            h('button', { class: 'btn sm', type: 'button', onclick: () => fileIn.click(), text: 'Import a .zip' }),
            fileIn,
            importMsg,
            h('button', { class: 'btn sm', type: 'button', onclick: () => exportZip(ctx), text: 'Export as .zip' }),
            h('span', { class: 'grow' }),
            h('button', { class: 'btn sm ghost', type: 'button', onclick: () => { dev.setUnlocked(false); ctx.ui.devPage = false; ctx.rerender(); }, text: 'Lock' }),
        ];

        // What it learned, in plain words.
        const lines = [...describeGym(gym), ...describeFights(fights).filter((l) => !(set.fights.every((x) => !Number.isFinite(x.hpKept)) && /\bHP\b/.test(l)))];
        const learned = h('div', { class: 'lead' }, [
            sectionHead('What it learned', meta(['in plain words · each change was kept only because it predicted newer ' + (src === 'friend' ? 'sessions' : 'trains') + ' better'])),
            h('ul', { class: 'heads num' }, lines.map((l) => h('li', { class: /now counts|corrected|found|Kept/i.test(l) ? 'g' : null }, [h('i'), h('div', { text: l })]))),
            gym && gym.reasons && gym.reasons.length ? h('div', { class: 'note2', text: 'Gym: ' + gym.reasons.join(' ') }) : null,
        ]);

        // Each session: what it said (before) and with the learned model, against what you got.
        const mult = gym && gym.accepted ? gym.model.mult : null;
        const pts = [];
        for (const s of set.samples.slice(-200)) {
            if (!(s.predicted > 0) || !(s.actual > 0)) continue;
            pts.push({ x: s.predicted, y: s.actual, c: 'var(--muted)' });
            if (mult) pts.push({ x: s.predicted * (mult[s.stat] || 1), y: s.actual, c: STAT_COLOR[s.stat] || 'var(--chalk)' });
        }
        const scat = h('div', {}, [
            sectionHead('Each session', meta(['what it said vs what you got' + (mult ? ' · grey before, coloured now' : '')]), null, 'h3'),
            pts.length ? scatter(pts, { w: 520, h: 240, xl: 'it said', yl: 'you got', label: 'Predicted against actual gain per session' }) : h('p', { class: 'muted', style: 'margin:0', text: 'No sessions yet: one stat trained between two reads, with no drug, booster or refill in between, makes one.' }),
        ]);

        // Error on newer sessions, over time (from the learning runs).
        const log = dev.log();
        const errRows = log.filter((r) => r.gym && r.gym.heldOut && r.gym.heldOut.current !== null);
        const errChart = h('div', {}, [
            sectionHead('Error on newer sessions', meta(['over time · before vs the learned model']), null, 'h3'),
            errRows.length >= 2
                ? lineChart([{ name: 'before', color: 'var(--muted)', dash: '5 4', values: errRows.map((r) => r.gym.heldOut.current), label: 'before' }, { name: 'now', color: 'var(--chalk)', width: 2.5, values: errRows.map((r) => r.gym.heldOut.learned), label: 'learned' }], { w: 520, h: 160, left: 36, right: 70, xLabels: [[0, dateShort(errRows[0].at)], [errRows.length - 1, dateShort(errRows[errRows.length - 1].at)]], grid: [0, Math.max(...errRows.map((r) => Math.max(r.gym.heldOut.current, r.gym.heldOut.learned || 0)))], label: 'Held-out error over time' })
                : h('p', { class: 'muted', style: 'margin:0', text: 'Shows after two learning runs with enough newer sessions to test on (' + errRows.length + ' so far).' }),
        ]);

        // Torn Eye: when it said you'd win, how often you did.
        const bins = (fights && fights.bins) || [];
        const eye = h('div', {}, [
            sectionHead('Torn Eye', meta(['when it said you’d win, how often you did · bar = what happened, line = what it said']), null, 'h3'),
            bins.some((b) => b.fights)
                ? bars(bins.filter((b) => b.fights).map((b) => ({ v: 100 * b.won, ref: 100 * b.predicted, c: 'var(--good)', label: Math.round(b.from * 100) + '–' + Math.round(b.to * 100) + '%', top: b.fights + ' fights' })), { w: 520, h: 160, max: 100, label: 'Win rate by predicted win chance' })
                : h('p', { class: 'muted', style: 'margin:0', text: 'Needs fights with a prediction before them: Torn Eye saves what it said when you open an attack page. ' + set.fights.length + ' so far. Spotting a 10% error takes about 2,000 fights, so this changes slowly by design.' }),
        ]);

        // Pane: learned values, the self-check, the export, raw.
        const firstAccepted = (pred) => log.find(pred);
        const valRows = [];
        for (const k of STATS) {
            const v = gym && gym.model ? gym.model.mult[k] : 1;
            const when = firstAccepted((r) => r.gym && r.gym.accepted && Math.abs((r.gym.mult || {})[k] - 1) > 1e-6);
            valRows.push(h('tr', {}, [h('td', { text: STAT_LABEL[k] + ' gain ×' }), h('td', { class: 'r', text: (gym && gym.accepted ? v : 1).toFixed(3) }), h('td', { class: 'muted', text: gym && gym.accepted && Math.abs(v - 1) > 1e-6 ? (when ? dateShort(when.at) : 'now') : 'kept' })]));
        }
        valRows.push(h('tr', {}, [h('td', { text: 'Above-50M formula' }), h('td', { class: 'r', text: gym && gym.model ? gym.model.mode : 'log10' }), h('td', { class: 'muted', text: gym && gym.accepted && gym.model.mode !== (gym.current && gym.current.mode) ? 'changed' : 'kept' })]));
        valRows.push(h('tr', {}, [h('td', { text: 'Win odds ×' }), h('td', { class: 'r', text: fights && fights.accepted ? fights.model.winScale.toFixed(2) : '1.00' }), h('td', { class: 'muted', text: fights && fights.winAccepted ? 'changed' : 'kept' })]));
        // HP kept is learned only once fights carry what was really kept (not read yet): no row until then.
        if (set.fights.some((x) => Number.isFinite(x.hpKept))) valRows.push(h('tr', {}, [h('td', { text: 'HP kept ×' }), h('td', { class: 'r', text: fights && fights.accepted ? fights.model.hpScale.toFixed(2) : '1.00' }), h('td', { class: 'muted', text: fights && fights.hpAccepted ? 'changed' : 'kept' })]));
        const noHp = !set.fights.some((x) => Number.isFinite(x.hpKept));

        const checks = ctx.ui.devChecks || null;
        const sizes = dev.sizes();
        const pane = [
            h('div', {}, [sectionHead('Learned values', meta(['and when they changed']), null, 'h3'), h('table', { class: 'tbl num' }, [h('tbody', {}, valRows)])]),
            h('div', {}, [
                sectionHead('Simulation check', meta([checks ? 'run just now' : 'runs here in a moment']), null, 'h3'),
                checks
                    ? h('dl', { class: 'facts num' }, checks.flatMap((c) => [h('dt', { text: c.name }), h('dd', { class: c.ok ? 'c-good' : 'c-bad', text: c.text })]))
                    : h('button', { class: 'btn sm', type: 'button', onclick: () => { ctx.ui.devChecks = selfCheck(); ctx.rerender(); }, text: 'Run S1 + S2' }),
                h('div', { class: 'note2', text: 'The full suite (S1–S4, fights F1–F3) runs with node --test test/learn.test.js.' }),
            ]),
            h('div', {}, [
                sectionHead('Export', meta(['what the .zip holds']), null, 'h3'),
                h('dl', { class: 'facts num' }, [h('dt', { text: 'gym-samples.json' }), h('dd', { text: mine.samples.length + ' sessions' }), h('dt', { text: 'fights.json' }), h('dd', { text: mine.fights.length + ' fights' }), h('dt', { text: 'model.json' }), h('dd', { text: 'learned values' }), h('dt', { text: 'meta.json' }), h('dd', { text: 'version, date' })]),
                h('div', { class: 'note2', text: 'Names and player ids are left out; stats rounded. Nothing is uploaded: the file downloads to this computer.' }),
            ]),
            h('div', {}, [
                h('details', { class: 'dis' }, [
                    h('summary', { text: 'Raw for Claude · accept log, scores, storage' }),
                    h('pre', { style: 'white-space:pre-wrap;font-size:12px;color:var(--muted);margin:8px 0 0' }, [
                        log.slice(-12).map((r) => new Date(r.at).toISOString().slice(0, 16) + ' gym ' + (r.gym.candidates || []).map((c) => c.mode + ' ' + (c.error === null ? '—' : c.error.toFixed(2) + '%')).join(' / ') + ' · held-out ' + (r.gym.heldOut.current === null ? '—' : r.gym.heldOut.current.toFixed(2) + '% → ' + r.gym.heldOut.learned.toFixed(2) + '%') + ' · ' + (r.gym.accepted ? 'ACCEPT' : 'keep') + ' · eye ' + (r.fights.accepted ? 'ACCEPT' : 'keep') + ' (' + r.fights.fights + ')').join('\n') || 'no learning runs yet',
                        '\n\nstorage: ' + Object.entries(sizes).map(([k, v]) => k + ' ' + fmtInt(v) + ' B').join(' · '),
                    ]),
                ]),
            ]),
        ];
        return { ctl: [ctl], main: [learned, scat, errChart, eye, moneyFieldsBlock(dev)], pane };
    }

    void fmtPct;

    /* ===== src/ui/app/report.js ===== */
    /*
     * Settings › Report a problem (round 7; Torn Trading's "Report a problem"
     * in Pumping Iron's own Settings look): say what happened and what you
     * expected, add screenshots, see what goes in the zip before anything is
     * made, then download one file to send. Nothing is sent by this page.
     */







    /**
     * What you typed and attached lives here, not in the page's `ui` (that one is
     * compared on every redraw; screenshots are megabytes).
     */
    const reportFormState = { happened: '', expected: '', shots: [], showLog: false, status: '', lastZip: null };

    const reportStamp = (ms) => new Date(ms).toISOString().slice(0, 16).replace(/[-:]/g, '').replace('T', '-');

    function saveReportZip(zip) {
        const url = URL.createObjectURL(new Blob([zip.data], { type: 'application/zip' }));
        const a = h('a', { href: url, download: zip.name, style: 'display:none' });
        document.body.appendChild(a);
        a.click();
        setTimeout(() => {
            URL.revokeObjectURL(url);
            a.remove();
        }, 10000);
    }

    /** The zip's files from what the page holds now (also used by the browser check). */
    function buildReport(ctx, now = Date.now()) {
        const r = ctx.report.data();
        const learning = exportFiles({ samples: r.learn.samples, fights: r.learn.fights, gymLog: r.learn.gymLog, learned: r.learn.learned, version: r.state.version, now });
        return reportFiles({ happened: reportFormState.happened, expected: reportFormState.expected, shots: reportFormState.shots, log: r.log, state: r.state, player: r.player, saved: r.saved, learning, moneyFields: r.moneyFields, statsHistory: r.statsHistory, env: r.env, now });
    }

    function downloadReport(ctx) {
        const now = Date.now();
        reportFormState.lastZip = { data: makeZip(buildReport(ctx, now), now), name: 'pumping-iron-report-' + reportStamp(now) + '.zip' };
        saveReportZip(reportFormState.lastZip);
        // One file, then a clean form: the words, the screenshots and the log go, so the next report starts empty.
        for (const s of reportFormState.shots) URL.revokeObjectURL(s.url);
        reportFormState.happened = '';
        reportFormState.expected = '';
        reportFormState.shots = [];
        ctx.report.clearLog();
        reportFormState.status = 'Saved ' + reportFormState.lastZip.name + ' to your downloads. Send that file: nothing was sent by this page. The form and the log are cleared for your next report.';
        ctx.rerender();
    }

    /** The Settings card. */
    function reportSection(m, ctx) {
        if (!ctx.report) return null;
        const r = ctx.report.data();
        const errors = r.log.filter((e) => e.kind === 'error').length;
        const happened = h('textarea', { class: 'inp ta', rows: '4', 'aria-label': 'What happened', placeholder: 'For example: I pressed Re-plan for 12 months, the bar stopped at "month 5" and nothing changed.' });
        happened.value = reportFormState.happened;
        happened.addEventListener('input', () => (reportFormState.happened = happened.value));
        const expected = h('textarea', { class: 'inp ta', rows: '2', 'aria-label': 'What you expected', placeholder: 'For example: the new plan in a few seconds.' });
        expected.value = reportFormState.expected;
        expected.addEventListener('input', () => (reportFormState.expected = expected.value));
        const file = h('input', { type: 'file', accept: 'image/*', multiple: true, style: 'display:none' });
        file.addEventListener('change', () => {
            const files = [...(file.files || [])];
            file.value = '';
            Promise.all(files.map((f) => f.arrayBuffer().then((b) => ({ name: f.name, data: new Uint8Array(b), url: URL.createObjectURL(f) })))).then((got) => {
                reportFormState.shots.push(...got);
                ctx.rerender();
            });
        });
        const shots = reportFormState.shots.map((s, i) =>
            h('span', { class: 'shot' }, [
                h('img', { src: s.url, alt: s.name }),
                h('button', { type: 'button', class: 'x', 'aria-label': 'Remove ' + s.name, onclick: () => { URL.revokeObjectURL(s.url); reportFormState.shots.splice(i, 1); ctx.rerender(); }, text: '×' }),
            ]),
        );
        const includes = reportIncludes({ shots: reportFormState.shots.length, log: r.log, player: r.player, saved: r.saved, gymLog: r.learn.gymLog.length, moneyTypes: (r.moneyFields || []).length });
        const state = h('span', { class: 'state ' + (errors ? 'bad' : 'off') }, [h('i'), errors ? errors + (errors === 1 ? ' error logged' : ' errors logged') : 'Nothing logged as an error']);
        return h('div', { class: 'sec' }, [
            h('div', {}, [h('h3', { text: 'Report a problem' }), state]),
            h('div', { class: 'secbody' }, [
                h('p', { text: 'Found a bug, or something slow? Say what happened, add screenshots, and download one .zip to send. It also holds the problem log (what failed, what you clicked just before, how long each plan took) and your stats, gym log and saved plan, so the cause is found without guessing. Nothing is sent anywhere by this page.' }),
                h('label', { class: 'field' }, [h('span', { class: 'lab', text: 'What happened?' }), happened]),
                h('label', { class: 'field' }, [h('span', { class: 'lab', text: 'What did you expect?' }), expected]),
                h('div', { class: 'row', style: 'flex-wrap:wrap' }, [h('button', { class: 'btn sm', type: 'button', onclick: () => file.click(), text: 'Add screenshots' }), h('span', { class: 'muted', style: 'font-size:13px', text: 'Win + Shift + S takes one; save it, then add it here.' }), file]),
                shots.length ? h('div', { class: 'shots' }, shots) : null,
                h('div', {}, [h('span', { class: 'lab', text: 'What goes in the zip' }), h('ul', { class: 'incl' }, includes.map((x) => h('li', { text: x })))]),
                h('div', { class: 'row', style: 'flex-wrap:wrap' }, [
                    h('button', { class: 'btn primary', type: 'button', onclick: () => downloadReport(ctx), text: 'Download report (.zip)' }),
                    reportFormState.lastZip ? h('button', { class: 'btn sm ghost', type: 'button', onclick: () => saveReportZip(reportFormState.lastZip), text: 'Download it again' }) : null,
                    h('button', { class: 'btn sm ghost', type: 'button', 'aria-expanded': String(reportFormState.showLog), onclick: () => { reportFormState.showLog = !reportFormState.showLog; ctx.rerender(); }, text: reportFormState.showLog ? 'Hide the log' : 'Show the log' }),
                    h('button', { class: 'btn sm ghost', type: 'button', title: 'Start the log again (after sending a report)', onclick: () => { ctx.report.clearLog(); reportFormState.status = 'Log cleared.'; ctx.rerender(); }, text: 'Clear the log' }),
                ]),
                reportFormState.status ? h('span', { class: 'msg ok', role: 'status', text: reportFormState.status }) : null,
                reportFormState.showLog ? h('pre', { class: 'logbox num', text: logAsText(r.log.slice(-40)).trim() || 'Nothing logged yet.' }) : null,
                h('details', { class: 'dis' }, [h('summary', { text: 'What is and isn’t in the file' }), h('p', { text: 'In it: what you wrote, your screenshots, the problem log, your stats (the four numbers), happy and energy maximum, gym and gyms unlocked, build, the perk lines Torn lists for you, your saved plan in short, the last plan runs with their time, your stats history, your trains from Torn’s log, and your money log by type with the names of its fields. Not in it: any API key, your player id or name, other players’ ids or names, any money log amount.' })]),
            ]),
        ]);
    }

    /** For tests: the form's state. */
    const reportForm = reportFormState;

    /* ===== src/ui/app/settings.js ===== */
